 using Microsoft.AspNetCore.Mvc;
 using Microsoft.Extensions.ML;
 using Microsoft.ML;
 using Microsoft.ML.Data;
 using TicketClassifier.Models;
 using TicketClassifier.Services;

 namespace TicketClassifier.Controllers;

 [ApiController]
 [Route("api/[controller]")]
 public class TicketController : ControllerBase
 {
     private readonly PredictionEnginePool<TicketInput, TicketPrediction> _predictionPool;
     private readonly ModelTrainingService _trainingService;

     private static readonly string ModelPath = Path.Combine("Data", "model.zip");
     private static readonly string DataPath = Path.Combine("Data", "tickets.csv");

     public TicketController(
         PredictionEnginePool<TicketInput, TicketPrediction> predictionPool,
         ModelTrainingService trainingService)
     {
         _predictionPool = predictionPool;
         _trainingService = trainingService;
     }

     /// <summary>Train (or retrain) the model from the CSV data.</summary>
     [HttpPost("train")]
     public IActionResult Train()
     {
         var metricsReport = _trainingService.TrainAndSave(DataPath, ModelPath);
         return Ok(new { message = "Model trained successfully", metrics = metricsReport });
     }

     /// <summary>Predict the category for a support ticket.</summary>
     [HttpPost("predict")]
     public IActionResult Predict([FromBody] TicketRequest request)
     {
         if (!System.IO.File.Exists(ModelPath))
             return BadRequest(new { error = "Model not trained yet. POST /api/ticket/train first." });

         var input = new TicketInput
         {
             Subject = request.Subject,
             Description = request.Description,
             Priority = request.Priority
         };

         var prediction = _predictionPool.Predict(input);

         // Read label names from the trained model's Score column metadata
         var mlContext = new MLContext();
         using var stream = System.IO.File.OpenRead(ModelPath);
         var model = mlContext.Model.Load(stream, out var schema);
         var transformedSchema = model.GetOutputSchema(schema);
         var scoreColumn = transformedSchema["Score"];

         var slotNames = new VBuffer<ReadOnlyMemory<char>>();
         scoreColumn.GetSlotNames(ref slotNames);
         var labelNames = slotNames.DenseValues().Select(v => v.ToString()).ToArray();

         var scores = new Dictionary<string, float>();
         for (var i = 0; i < prediction.Score.Length && i < labelNames.Length; i++)
             scores[labelNames[i]] = prediction.Score[i];

         return Ok(new TicketResponse
         {
             PredictedCategory = prediction.PredictedCategory,
             Scores = scores
         });
     }
 }

